def transform(grid):
    out = [row[:] for row in grid]
    bg = grid[0][0]
    active = [r for r, row in enumerate(grid) if any(v != bg for v in row)]
    half = len(active) // 2
    # Rows encode corresponding parts of two patterns. Extend the row with
    # the shorter rightmost extent to match the other row, marking the added
    # cells in color 1.
    for a, b in zip(active[:half], active[half:]):
        enda = max((c for c, v in enumerate(grid[a]) if v != bg), default=-1)
        endb = max((c for c, v in enumerate(grid[b]) if v != bg), default=-1)
        if enda < endb:
            for c in range(enda + 1, endb + 1):
                if grid[a][c] == bg:
                    out[a][c] = 1
        elif endb < enda:
            for c in range(endb + 1, enda + 1):
                if grid[b][c] == bg:
                    out[b][c] = 1
    return out

