 "content": "def transform(grid):
    out = [row[:] for row in grid]
    bg = grid[0][0]
    for r, row in enumerate(grid):
        # Find the shortest period (1..6) in the non-background suffix and
        # continue its foreground cells as marker 1 through the blank tail.
        end = max((c for c, v in enumerate(row) if v != bg), default=-1) + 1
        if end == len(row) or end == 0:
            continue
        start = 0
        while start < end and row[start] == bg:
            start += 1
        seq = row[start:end]
        period = None
        for p in range(1, min(6, len(seq)) + 1):
            if all(seq[i] == seq[i % p] for i in range(len(seq))):
                period = p
                break
        if period is None:
            continue
        for c in range(end, len(row)):
            if row[c] == bg and seq[(c - start) % period] != bg:
                out[r][c] = 1
    return out
"
}

